// Program.cs
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer();                                  // 1) how identity is proven

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("CanModerate", policy =>
        policy.RequireRole("Moderator")
              .RequireClaim("email_verified", "true")); // 2) what identity may do
});

app.UseAuthentication();  // establishes ClaimsPrincipal (or 401)
app.UseAuthorization();   // evaluates policy on the matched endpoint (or 403)

// Controller
[Authorize]                                        // signed-in users only
public class OrdersController : ControllerBase
{
    [HttpGet("{id}")]
    public IActionResult Get(Guid id) => Ok();

    [Authorize(Policy = "CanModerate")]             // extra rule for this action
    [HttpDelete("{id}")]
    public IActionResult Delete(Guid id) => NoContent();

    [AllowAnonymous]                                // identity not required
    [HttpGet("../health")]
    public IActionResult Health() => Ok();
}
